module.content:
&lt;ActionGrid&gt;
  &lt;Settings&gt;
    &lt;Version&gt;5.28.0&lt;/Version&gt;
    &lt;Build&gt;5.28.314&lt;/Build&gt;
    &lt;CurrentContext&gt;ExportImport&lt;/CurrentContext&gt;
    &lt;ModuleId&gt;1004&lt;/ModuleId&gt;
    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;SELECT 
p.CodBeneficiar as Id,
    p.CodBeneficiar,
    p.CodSucursala,
    p.Anul,
    p.Luna,

    r.DenumireBeneficiar,

    UPPER(e.TipFisier) AS TipFisier,
    e.Email,

    --  TOTALURI
    SUM(p.ContributiePersonala) AS TotalCP,
    SUM(p.ContributieAngajator) AS TotalCA,
    SUM(p.ContributieTotala) AS TotalCT,

    SUM(p.ContributiePersonalaRetinuta) AS TotalRetinut,
    SUM(p.ContributieAngajatorVirata) AS TotalAngajatorVirat,
    SUM(p.ContributieTotalaVirata) AS TotalVirat,

    -- ⚖️ DIFERENTA
    SUM(p.ContributiePersonala) 
        - SUM(p.ContributiePersonalaRetinuta) AS Diferenta,

    --  STATUS
    CASE 
        WHEN SUM(p.ContributiePersonala) &amp;lt;&amp;gt; SUM(p.ContributiePersonalaRetinuta)
            THEN &#39;DIFERENTA&#39;
        ELSE &#39;OK&#39;
    END AS Status,

    --  CSS
    CASE 
        WHEN SUM(p.ContributiePersonala) &amp;lt;&amp;gt; SUM(p.ContributiePersonalaRetinuta)
            THEN &#39;row-diff&#39;
        ELSE &#39;&#39;
    END AS RowClass,

    --  TOTAL GENERAL
    SUM(SUM(p.ContributiePersonala)) OVER() AS SumTotalCP,
    SUM(SUM(p.ContributieAngajator)) OVER() AS SumTotalCA,
    SUM(SUM(p.ContributieTotala)) OVER() AS SumTotalCT

FROM app.PensieFacultativa p

--  Email (atenție la duplicare)
LEFT JOIN app.PensieFacultativaEmail e 
    ON e.CodBeneficiar = p.CodBeneficiar

--  Beneficiar DISTINCT + denumire
JOIN (
    SELECT 
        CodBeneficiar,
        CodSucursala,
        MAX(DenumireBeneficiar) AS DenumireBeneficiar
    FROM app.NomBeneficiarRetinere
    WHERE tiprataold = 7
    GROUP BY CodBeneficiar, CodSucursala
) r
    ON p.CodBeneficiar = r.CodBeneficiar
   AND p.CodSucursala = r.CodSucursala

WHERE 
    p.Anul = @Anul
    AND p.Luna = @Luna
    AND p.CodSucursala = @CodSucursala
    AND p.ContributieTotalaVirata &amp;gt; 0

GROUP BY 
    p.CodBeneficiar,
    p.CodSucursala,
    p.Anul,
    p.Luna,
    r.DenumireBeneficiar,
    e.TipFisier,
    e.Email

ORDER BY 
    p.CodBeneficiar,r.DenumireBeneficiar&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;IdColumn&quot;:&quot;Id&quot;,&quot;SqlQueryColumns&quot;:&quot;&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:&quot;Id&quot;,&quot;Name&quot;:&quot;Id&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;CodBeneficiar&quot;,&quot;Name&quot;:&quot;CodBeneficiar&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;CodSucursala&quot;,&quot;Name&quot;:&quot;CodSucursala&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Anul&quot;,&quot;Name&quot;:&quot;Anul&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Luna&quot;,&quot;Name&quot;:&quot;Luna&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;DenumireBeneficiar&quot;,&quot;Name&quot;:&quot;DenumireBeneficiar&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TipFisier&quot;,&quot;Name&quot;:&quot;TipFisier&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Email&quot;,&quot;Name&quot;:&quot;Email&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TotalCP&quot;,&quot;Name&quot;:&quot;TotalCP&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TotalCA&quot;,&quot;Name&quot;:&quot;TotalCA&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TotalCT&quot;,&quot;Name&quot;:&quot;TotalCT&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TotalRetinut&quot;,&quot;Name&quot;:&quot;TotalRetinut&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TotalAngajatorVirat&quot;,&quot;Name&quot;:&quot;TotalAngajatorVirat&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TotalVirat&quot;,&quot;Name&quot;:&quot;TotalVirat&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Diferenta&quot;,&quot;Name&quot;:&quot;Diferenta&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Status&quot;,&quot;Name&quot;:&quot;Status&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;RowClass&quot;,&quot;Name&quot;:&quot;RowClass&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;SumTotalCP&quot;,&quot;Name&quot;:&quot;SumTotalCP&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;SumTotalCA&quot;,&quot;Name&quot;:&quot;SumTotalCA&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;SumTotalCT&quot;,&quot;Name&quot;:&quot;SumTotalCT&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null}]}&lt;/DataSource&gt;
    &lt;ShowTitle&gt;True&lt;/ShowTitle&gt;
    &lt;NoDataMessage&gt;No Data&lt;/NoDataMessage&gt;
    &lt;AditionalHtmlHeader /&gt;
    &lt;OnInitJs /&gt;
    &lt;OnRefreshJs /&gt;
    &lt;EnableEmbed&gt;False&lt;/EnableEmbed&gt;
    &lt;ShowCondition /&gt;
    &lt;SearchPlaceholder&gt;Search&lt;/SearchPlaceholder&gt;
    &lt;SearchDelayTime&gt;300&lt;/SearchDelayTime&gt;
    &lt;TableHeight /&gt;
    &lt;PagerStyle&gt;TouchFriendly&lt;/PagerStyle&gt;
    &lt;DisplayMode&gt;Always&lt;/DisplayMode&gt;
    &lt;PopupWidth /&gt;
    &lt;WidthCoordinate&gt;px&lt;/WidthCoordinate&gt;
    &lt;PopupName /&gt;
    &lt;PageSizes&gt;[12,24,48]&lt;/PageSizes&gt;
    &lt;DefaultPageSize&gt;12&lt;/DefaultPageSize&gt;
    &lt;IsDebug&gt;False&lt;/IsDebug&gt;
    &lt;SearchEnabled&gt;True&lt;/SearchEnabled&gt;
    &lt;ExactSearch&gt;False&lt;/ExactSearch&gt;
    &lt;HideEmptyGrid&gt;False&lt;/HideEmptyGrid&gt;
    &lt;LoadOnSearch&gt;False&lt;/LoadOnSearch&gt;
    &lt;HideTableHead&gt;False&lt;/HideTableHead&gt;
    &lt;EnableStickyHead&gt;False&lt;/EnableStickyHead&gt;
    &lt;ItemButtonPosition&gt;Right&lt;/ItemButtonPosition&gt;
    &lt;ItemButtonPositionInColumn&gt;Right&lt;/ItemButtonPositionInColumn&gt;
    &lt;ItemButtonGroupingOptions&gt;HorizontalAlign&lt;/ItemButtonGroupingOptions&gt;
    &lt;FiltersEnabled&gt;True&lt;/FiltersEnabled&gt;
    &lt;ShowFilters&gt;False&lt;/ShowFilters&gt;
    &lt;SyncUrl&gt;False&lt;/SyncUrl&gt;
    &lt;IncludeBootstrapJS&gt;True&lt;/IncludeBootstrapJS&gt;
    &lt;IncludeBootstrapCSS&gt;True&lt;/IncludeBootstrapCSS&gt;
    &lt;IncludeFontAwesome&gt;True&lt;/IncludeFontAwesome&gt;
    &lt;AngularnoConflict&gt;True&lt;/AngularnoConflict&gt;
    &lt;SelectAllPosition&gt;None&lt;/SelectAllPosition&gt;
    &lt;SearchPosition&gt;top&lt;/SearchPosition&gt;
    &lt;RootCSSClasses /&gt;
    &lt;ModalRefresh&gt;False&lt;/ModalRefresh&gt;
    &lt;ShowLoading&gt;True&lt;/ShowLoading&gt;
    &lt;TabsProLoading&gt;True&lt;/TabsProLoading&gt;
    &lt;EnableGridSelect&gt;True&lt;/EnableGridSelect&gt;
    &lt;DataSourceAutoRefreshInterval&gt;1&lt;/DataSourceAutoRefreshInterval&gt;
    &lt;DataSourceRefreshType&gt;manual&lt;/DataSourceRefreshType&gt;
    &lt;DateFormat&gt;m/d/yy&lt;/DateFormat&gt;
    &lt;ItemButtonGroups&gt;[]&lt;/ItemButtonGroups&gt;
    &lt;GridButtonGroups&gt;[]&lt;/GridButtonGroups&gt;
    &lt;ItemButtons&gt;[]&lt;/ItemButtons&gt;
    &lt;GridButtons&gt;[{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;All&quot;,&quot;SumCoefficient&quot;:&quot;0&quot;,&quot;TextBeforeSum&quot;:&quot;Total:&quot;,&quot;TextAfterSum&quot;:&quot;LEI&quot;,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Top&quot;,&quot;HorizontalPosition&quot;:&quot;Right&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;cd95ed3b-7a16-4a59-b0ca-eecce39892e8&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:&quot;&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;1&quot;,&quot;EntireGroup&quot;:false,&quot;Entry&quot;:&quot;96750a11-0461-4f93-b8c3-73831454ac76&quot;},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;WITH BaseData AS (
    SELECT 
        p.CodBeneficiar as Id,
        p.CodBeneficiar,
        p.CodSucursala,
        p.Anul,
        p.Luna,
        r.DenumireBeneficiar,
        UPPER(e.TipFisier) AS TipFisier,
        e.Email,

        SUM(p.ContributiePersonala) AS TotalCP,
        SUM(p.ContributieAngajator) AS TotalCA,
        SUM(p.ContributieTotala) AS TotalCT,

        SUM(p.ContributiePersonalaRetinuta) AS TotalRetinut,
        SUM(p.ContributieAngajatorVirata) AS TotalAngajatorVirat,
        SUM(p.ContributieTotalaVirata) AS TotalVirat,

        SUM(p.ContributiePersonala) 
            - SUM(p.ContributiePersonalaRetinuta) AS Diferenta,

        CASE 
            WHEN SUM(p.ContributiePersonala) &amp;lt;&amp;gt; SUM(p.ContributiePersonalaRetinuta)
                THEN &#39;DIFERENTA&#39;
            ELSE &#39;OK&#39;
        END AS Status

    FROM app.PensieFacultativa p
    LEFT JOIN app.PensieFacultativaEmail e 
        ON e.CodBeneficiar = p.CodBeneficiar
    JOIN (
        SELECT CodBeneficiar, CodSucursala,
               MAX(DenumireBeneficiar) AS DenumireBeneficiar
        FROM app.NomBeneficiarRetinere
        WHERE tiprataold = 7
        GROUP BY CodBeneficiar, CodSucursala
    ) r
        ON p.CodBeneficiar = r.CodBeneficiar
       AND p.CodSucursala = r.CodSucursala
    WHERE 
        p.Anul = @Anul
        AND p.Luna = @Luna
        AND p.CodSucursala = @CodSucursala
        AND p.ContributieTotalaVirata &amp;gt; 0
    GROUP BY 
        p.CodBeneficiar,
        p.CodSucursala,
        p.Anul,
        p.Luna,
        r.DenumireBeneficiar,
        e.TipFisier,
        e.Email
)

SELECT 
    b.CodBeneficiar,
    b.CodSucursala,
    b.Anul,
    b.Luna,
    b.DenumireBeneficiar,
    b.TotalCP,
    b.TotalCA,
    b.TotalCT,
    b.TotalRetinut,
    b.TotalAngajatorVirat,
    b.TotalVirat,
    b.Diferenta,
    b.Status,

    -- TOTALURI (aceleași pe fiecare r&#226;nd pentru Word)
    SUM(b.TotalCP) OVER() AS SumTotalCP,
    SUM(b.TotalCA) OVER() AS SumTotalCA,
    SUM(b.TotalCT) OVER() AS SumTotalCT

FROM BaseData b
ORDER BY b.DenumireBeneficiar&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:&quot;MyList&quot;,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false,&quot;UseTransactions&quot;:true},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;666009e5-f5ab-4cb8-ac31-5abe97fc1a60&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;ApplyTokens&quot;,&quot;Condition&quot;:&quot;0&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Tokens&quot;:[{&quot;value&quot;:&quot;[MyList:CodSucursala]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[MyList:Anul]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[MyList:Luna]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;TokenizeTokenNames&quot;:false,&quot;RecursionCount&quot;:&quot;1&quot;},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;2b3a92a9-1deb-4413-9908-86eb8848dc08&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;ReplaceTokensWord&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:2,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;FileIdentifier&quot;:&quot;ExportFisiere/Templates/PensiiFacultative/CentralizatorPF.docx&quot;,&quot;Folder&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;/ExportFisiere/PensiiFacultative&quot;},&quot;Pattern&quot;:&quot;[GetOrSession:BranchV]_CentralizatorPF_[GetOrSession:MonthV][GetOrSession:YearV]&quot;,&quot;Duplicates&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;Overwrite&quot;},&quot;OutputTokenName&quot;:&quot;WordFile&quot;},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;eb1ebca1-9d7b-49f1-a527-47833a1c7535&quot;,&quot;Description&quot;:&quot;Info Fisier&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:&quot;0&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:3,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;SELECT f.FileId,
    f.FileName,
     --&#39;https://salarizareposta.apps.plantanapp.com/Portals/0/&#39; +
    Folder +
    FileName AS DownloadUrl 
FROM Files f

CROSS APPLY (
    SELECT RIGHT(LEFT(f.FileName, LEN(f.FileName) - 5), 6) AS LunaAn
) x

WHERE 
    f.Folder = &#39;ExportFisiere/PensiiFacultative/&#39;

